                ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
            } else {
                ctx.json(reservationToJson(reservation.get()));
            }
        } catch (Exception e) {
            ctx.status(500).json(error("INTERNAL_ERROR", e.getMessage()));
        }
    }

