        obj.addProperty("discount", String.format("%.2f", res.getDiscount()));
        obj.addProperty("total", String.format("%.2f", res.getTotal()));
        obj.addProperty("status", res.getStatus().getLabel());
        obj.addProperty("amountPaid", String.format("%.2f", res.getAmountPaid()));
        obj.addProperty("refund", res.getRefund() != null ? String.format("%.2f", res.getRefund()) : null);
